import{_ as e,k as t,v as n}from"./app-Xgp6P-Ux.js";import{t as r}from"./plugin-vue_export-helper-BDNMzG2s.js";var i=JSON.parse(`{"path":"/column/Python-Programming-Course/P01-Programming-thinking/03-People-started-programming-over-800-years-ago.html","title":"03-那艘会演奏音乐的船，其实藏着最早的“程序”","lang":"zh-CN","frontmatter":{"title":"03-那艘会演奏音乐的船，其实藏着最早的“程序”","icon":"read","date":"2025-04-11T15:05:37.000Z","author":"AI悦创","isOriginal":true,"sticky":false,"star":false,"article":true,"timeline":true,"image":false,"navbar":true,"sidebarIcon":true,"comment":true,"lastUpdated":true,"editLink":true,"backToTop":true,"toc":true,"feed":false,"seo":false,"head":[]},"git":{"createdTime":1669634625000,"updatedTime":1748754423000,"contributors":[{"name":"AndersonHJB","username":"AndersonHJB","email":"cleland1432803776@icloud.com","commits":18,"url":"https://github.com/AndersonHJB"},{"name":"AI悦创","username":"","email":"cleland1432803776@icloud.com","commits":4}],"changelog":[{"hash":"ff4587c74d1c76d3aac787d3c96ea9dd9fecd743","time":1748754423000,"email":"bornforthis@bornforthis.cn","author":"AndersonHJB","message":"更改文件夹名称"},{"hash":"871641c2877652b654f8565d255dea535a79ba90","time":1748751204000,"email":"bornforthis@bornforthis.cn","author":"AndersonHJB","message":"修改文件名称Python-Programming-Course"},{"hash":"b44db4c520933876a80fb48fe6f09ac7a07cceb7","time":1744696920000,"email":"bornforthis@bornforthis.cn","author":"AndersonHJB","message":"update"},{"hash":"9e879d912937331668900cf3abe9331c585c84fb","time":1744380394000,"email":"bornforthis@bornforthis.cn","author":"AndersonHJB","message":"update"},{"hash":"bba9b83fbe0788566c5a024c9e67e9afdb58208b","time":1744379978000,"email":"bornforthis@bornforthis.cn","author":"AndersonHJB","message":"update"},{"hash":"8d4bb0dcf269dc226d1efeeb85cb769441b08f5d","time":1744379885000,"email":"bornforthis@bornforthis.cn","author":"AndersonHJB","message":"update"},{"hash":"3a5afa791e1d5ec8771b3395396aa4a7fa397339","time":1744379595000,"email":"bornforthis@bornforthis.cn","author":"AndersonHJB","message":"从加扎利的音乐船到霍尔瑞斯的卡片机，我们看到的是：编程的本质，从来都不是代码，而是一种思考方式。"},{"hash":"cefa0fa98f5c4fe10e0a13f51dcbeed56c561871","time":1744355622000,"email":"bornforthis@bornforthis.cn","author":"AndersonHJB","message":"children: \\"structure\\","},{"hash":"1fb361b0e7576bc5783278667ab1922cf91272f5","time":1744355160000,"email":"bornforthis@bornforthis.cn","author":"AndersonHJB","message":"read"},{"hash":"1c35a6532eb53bd6ed2f2afd6f70564646e80c01","time":1744328990000,"email":"bornforthis@bornforthis.cn","author":"AndersonHJB","message":"去掉head"},{"hash":"aed1739bbe0401281f8fe9b23c9bcb44b448b9ac","time":1743333691000,"email":"bornforthis@bornforthis.cn","author":"AndersonHJB","message":"启用编辑链接，提升文档的可用性和用户体验"},{"hash":"f14b0cca174ae138ce78063f95445916775cebdb","time":1718679320000,"email":"aiyuechuang@gmail.com","author":"AndersonHJB","message":"11"},{"hash":"e6ce4e085767c4f5b781fafab34fce9bb8a77757","time":1717922615000,"email":"aiyuechuang@gmail.com","author":"AndersonHJB","message":"192.168.3.12"},{"hash":"698822ef18765f0a40a5fe8d17c8e37745f728e7","time":1717398270000,"email":"aiyuechuang@gmail.com","author":"AndersonHJB","message":"2024-06-03 15:03:05"},{"hash":"772c411a931f42f9f56579305c16a96c1c834525","time":1675582584000,"email":"cleland1432803776@icloud.com","author":"AI悦创","message":"update"},{"hash":"e6a0f505dee0408ae039742ed8b7c873f3ccba3b","time":1675328574000,"email":"cleland1432803776@icloud.com","author":"AI悦创","message":"添加 Python 教程"},{"hash":"cbb3a0f217ea57089ad27386b3127e612324b609","time":1675049774000,"email":"cleland1432803776@icloud.com","author":"AI悦创","message":"update"},{"hash":"610fee0943c20fde9f54fa74b604beca191c1a25","time":1674624916000,"email":"cleland1432803776@icloud.com","author":"AI悦创","message":"remove password"},{"hash":"f08aaa80880a7b22af128caca0dba27069f28dfa","time":1672843073000,"email":"cleland1432803776@icloud.com","author":"AndersonHJB","message":"修复文章日期"},{"hash":"76989bb701c8ac79bbc7e2e46050c8b08855befd","time":1670605630000,"email":"cleland1432803776@icloud.com","author":"AndersonHJB","message":"update"},{"hash":"86c50aa64ad737c1db38d74dbb5ec22bb6c5bbeb","time":1670575429000,"email":"cleland1432803776@icloud.com","author":"AndersonHJB","message":"update"},{"hash":"027da62f7fafa8a29d6f7ba006e9bff7ac22acfe","time":1669634625000,"email":"cleland1432803776@icloud.com","author":"AndersonHJB","message":"first commit"}]},"readingTime":{"minutes":6.04,"words":1812},"filePathRelative":"column/Python-Programming-Course/P01-Programming-thinking/03-People-started-programming-over-800-years-ago.md"}`),a={name:`03-People-started-programming-over-800-years-ago.md`};function o(r,i,a,o,s,c){return t(),e(`div`,null,[...i[0]||=[n(`<h2 id="_1-编程的本质-不是代码-而是思想" tabindex="-1"><a class="header-anchor" href="#_1-编程的本质-不是代码-而是思想"><span>1. 编程的本质：不是代码，而是思想</span></a></h2><p>你有没有想过，什么是“编程”？大多数人的第一反应，大概是：在电脑上写一堆代码，然后做出一个小游戏或者网站。尤其是你要是学过编程，可能会觉得这个问题太简单了，根本不用解释。</p><p>可实际上，<strong>编程真正的核心，并不是代码本身</strong>。而是：<strong>通过一系列指令，控制机器按照你的设定行动。</strong></p><p>而且你可能不知道，这种“控制机器的艺术”，其实在没有电脑的年代，就已经存在了。</p><h2 id="_2-回到800多年前-没有电脑-人也在-编程" tabindex="-1"><a class="header-anchor" href="#_2-回到800多年前-没有电脑-人也在-编程"><span>2. 回到800多年前：没有电脑，人也在“编程”</span></a></h2><p>要了解这段历史，我们得穿越回800多年前的中东。在阿拉伯帝国，有一位天才发明家，叫<strong>伊斯梅尔·阿尔·加扎利</strong>。他造出了一艘非常特别的小船——<strong>一艘会自动演奏音乐的机械船</strong>。</p><figure><img src="/assets/raw-20250411175059731-B8Ac42DF.png" alt="伊斯梅尔设计的音乐机器人" tabindex="0" loading="lazy"><figcaption>伊斯梅尔设计的音乐机器人</figcaption></figure><p>这艘船上，坐着几位贵族和国王，周围还有四位“音乐家”：一人打鼓、一人吹笛、一人弹竖琴，还有一人负责节奏。这些音乐家看上去惟妙惟肖，但他们不会说话、不会走动，因为他们其实是<strong>机械木偶</strong>。</p><p>那问题来了：这些木偶怎么会弹奏乐器呢？</p><p>秘诀在于——<strong>机关装置 + 编排顺序的“程序”</strong>。</p><figure><img src="/assets/Al-Jazari_A_Musical_robot-BsavhT8H.jpeg" alt="Al-Jazari_A_Musical_robot｜加扎利音乐船" tabindex="0" loading="lazy"><figcaption>Al-Jazari_A_Musical_robot｜加扎利音乐船</figcaption></figure><p>如果你玩过八音盒，就会懂这个原理。旋转的金属圆柱上有许多小突起，每个突起在旋转时碰触内部的金属片，从而发出乐声。加扎利用类似的设计原理，让不同位置的“突起”控制木偶动作，从而实现“编排音乐”。</p><p>更厉害的是，他还让这些突起的位置可以更换，<strong>也就是说，只要重新设置这些点，木偶就能演奏出全新的曲子</strong>！</p><p>这就是早期的“可编程”系统——没有电子设备，却依然能靠机械装置实现自动控制。</p><p>我尽可能收集了互联网上所拥有的视频资料，找到了一个视频并发布在网站上。有兴趣的可以访问看看：</p><ol><li>个人网站：<a href="https://bornforthis.cn/column/py/share/Kunstkammer-Wien-der-Schiffsautomat.html" target="_blank" rel="noopener noreferrer">https://bornforthis.cn/column/py/share/Kunstkammer-Wien-der-Schiffsautomat.html</a></li><li>B 站上传：<a href="https://www.bilibili.com/video/BV1B4dDYXEcv" target="_blank" rel="noopener noreferrer">https://www.bilibili.com/video/BV1B4dDYXEcv</a></li></ol><h2 id="_3-从机械音乐人-到数据革命的机器" tabindex="-1"><a class="header-anchor" href="#_3-从机械音乐人-到数据革命的机器"><span>3. 从机械音乐人，到数据革命的机器</span></a></h2><p>时间快进几百年，我们来到19世纪末的美国。这时候，另一个编程故事悄然展开。</p><p>当时，美国政府遇到一个大难题：<strong>人口普查。</strong></p><p>根据法律，每10年一次的大型统计工作，必须收集全美范围的年龄、性别、受教育程度、职业、健康情况等20多项数据。1880年那次统计，光是分析数据就花了整整<strong>9年</strong>，新一轮普查还没开始，上一轮的数据就已经过时了。</p><figure><img src="/assets/4f2c5d22503f6068006b6465153757fc-D65P7KTL.jpg" alt="霍尔瑞斯" tabindex="0" loading="lazy"><figcaption>霍尔瑞斯</figcaption></figure><p>为了改变这种效率低下的局面，一位年轻工程师站了出来：<strong>赫尔曼·霍尔瑞斯</strong>。</p><figure><img src="/assets/9e540b3c42edb209a43a00b9f6b4ef91-DfVBV7pT.jpg" alt="打孔卡片制表机｜图片来源：Adam Schuster" tabindex="0" loading="lazy"><figcaption>打孔卡片制表机｜图片来源：Adam Schuster</figcaption></figure><p>他设计出了一种名叫“<strong>打孔卡片制表机</strong>”的装置。原理也不复杂：在纸卡片上打孔，每个孔位代表一个信息，比如性别是“男”，年龄是“11岁”。然后把这些卡片送进机器，机器根据孔的位置读取数据，自动统计结果。</p><p>对于很多人来说，这种方法或许并不陌生。像考试时涂答题卡，就是和打孔卡非常相似的一种做法。通过安排孔位——也就是设定机器可识别的“语言”——来告诉设备要怎么处理、统计，这本身就已经算是编程了。</p><figure><img src="/assets/706e7e393a34774c836086d112506555-VZgpBHpy.jpg" alt="" tabindex="0" loading="lazy"><figcaption></figcaption></figure><p>你可以把它理解为<strong>19世纪的“扫码统计系统”</strong>，只是当时的“扫码”，靠的是小孔和机械触点。</p><p>为验证效果，政府搞了场比赛。霍尔瑞斯的机器，只花了<strong>半天</strong>就完成了任务，而其他人的手工方案则要几天甚至更久才能出结果。他凭此赢得了1890年普查的正式合同，并把分析时间从9年缩短到<strong>2年半</strong>！</p><p>更重要的是，霍尔瑞斯还给这台机器增加了扩展功能——不仅能做人口普查，还能处理商业、卫生等各种数据，成为早期“通用型信息处理系统”。</p><p>这项技术，后来发展成一家公司，就是今天科技巨头之一的 <strong>IBM</strong> 的前身。</p><h2 id="_4-那打孔卡片-跟现代编程有什么关系" tabindex="-1"><a class="header-anchor" href="#_4-那打孔卡片-跟现代编程有什么关系"><span>4. 那打孔卡片，跟现代编程有什么关系？</span></a></h2><p>你可能会问：打孔就打孔，跟写代码有啥关系？</p><p>这就要回到我们最开始说的那句话：<strong>编程的本质，是通过一组指令，让机器在正确的时间做正确的事。</strong></p><p>打孔就是在用“机器能识别的方式”表达这些指令。每张卡片相当于一段程序，多个卡片组合起来，就是一套复杂的逻辑流程。</p><p>只是那个年代，程序不是键盘输入的，而是靠人手一张张打孔。霍尔瑞斯本人曾一天打上百张卡片，手臂打得肿胀酸痛，可他也由此开启了信息自动处理的新时代。</p><p>之后，自动打孔机出现，工作更轻松了。再之后，“打孔卡片”演变成了<strong>程序语言</strong>、<strong>操作系统</strong>和我们今天使用的各类“编程工具”。</p><h2 id="_5-编程-不止是技能-更是看问题的方式" tabindex="-1"><a class="header-anchor" href="#_5-编程-不止是技能-更是看问题的方式"><span>5. 编程，不止是技能，更是看问题的方式</span></a></h2><p>从加扎利的音乐船到霍尔瑞斯的卡片机，我们看到的是：<strong>编程的本质，从来都不是代码，而是一种思考方式</strong>。</p><p>它让我们能提前设定规则、设计流程，让机器自动完成复杂任务。而这种能力，早在没有电脑的时候，人类就已经具备了。</p><p>所以，如果你正在学习编程，记住一件事：<strong>学习编程，不只是为了写代码，更是为了拥有掌控复杂系统的能力。</strong></p><p>这正是本书要带你感受到的编程魅力。下一篇，我们会继续探讨另一个重大发明，它直接促成了我们今天使用的“真正的电脑程序”。</p><h2 id="_6-选择题" tabindex="-1"><a class="header-anchor" href="#_6-选择题"><span>6. 选择题</span></a></h2><ol><li><p>霍尔瑞斯的公司是哪个大型公司的前身？</p><p>A. 微软</p><p>B. IBM</p><p>C. 谷歌</p></li><li><p>编程最早可以追溯到哪位发明家？</p><p>A. 伊斯梅尔·加扎利</p><p>B. 赫尔曼·霍尔瑞斯</p><p>C. 艾伦·图灵</p></li><li><p>霍尔瑞斯发明了什么机器统计人口数据？</p><p>A. 数据统计机</p><p>B. 自动计算机</p><p>C. 打孔制表机</p></li></ol>`,43)]])}var s=r(a,[[`render`,o]]);export{i as _pageData,s as default};